package com.familyfinance.loan; import com.familyfinance.shared.Money; import java.time.LocalDate;
public record LoanInstallmentResponse(long id,int installmentNo,LocalDate dueOn,String principal,String interest,LoanInstallmentStatus status,Long confirmedTransactionId,LocalDate paidOn,String cashAmount,Long paymentAccountId,Long cancelledByPrepaymentId,String precisePrincipalAmount,String preciseInterestAmount,String interestCarryAmount,String roundingPolicy,String principalRoundingAmount) { static LoanInstallmentResponse from(LoanInstallment i){return new LoanInstallmentResponse(i.getId(),i.getInstallmentNo(),i.getDueOn(),Money.formatCents(i.getPrincipalCents()),Money.formatCents(i.getInterestCents()),i.getStatus(),i.getConfirmedTransaction()==null?null:i.getConfirmedTransaction().getId(),i.getConfirmedTransaction()==null?null:i.getConfirmedTransaction().getOccurredOn(),Money.formatCents(Math.addExact(i.getPrincipalCents(),i.getInterestCents())),i.getConfirmedTransaction()==null?null:i.getConfirmedTransaction().getAccount().getId(),i.getCancelledByPrepaymentId(),text(i.getPrecisePrincipalAmount()),text(i.getPreciseInterestAmount()),text(i.getInterestCarryAmount()),i.getRoundingPolicy(),i.getPrecisePrincipalAmount()==null?null:text(i.getPrincipalAmount().subtract(i.getPrecisePrincipalAmount())));} private static String text(java.math.BigDecimal value){return value==null?null:value.toPlainString();} }
